def solution(n, prereqs):
    # Each round, scan from course 0 up and take the first course that is ready.
    # O(n * (n + E)): fine for small inputs, far too slow for 10,000 courses.
    pre = [[] for _ in range(n)]
    for a, b in prereqs:
        pre[a].append(b)
    done = [False] * n
    order = []
    for _ in range(n):
        pick = -1
        for c in range(n):
            if not done[c] and all(done[b] for b in pre[c]):
                pick = c
                break
        if pick == -1:
            return []   # nothing is ready: the rest sit on a loop
        done[pick] = True
        order.append(pick)
    return order
